{"path": "transpose.py", "content": "def transpose(text):
    if not text:
        return ""
    lines = text.split("\n")
    # Pad each row on the right to the longest row below it, so shorter
    # rows end up left-padded in the output but nothing is padded on the right.
    width = 0
    for i in range(len(lines) - 1, -1, -1):
        width = max(width, len(lines[i]))
        lines[i] = lines[i].ljust(width)
    return "\n".join(
        "".join(line[col] for line in lines if col < len(line))
        for col in range(width)
    )
"}

